#!/usr/bin/env bash
# Question 1: DNS record for ${Q1_HOST}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

cur="$(kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}')"
if [[ ! -f /root/.cka-coredns-Corefile ]]; then
  printf '%s\n' "$cur" > /root/.cka-coredns-Corefile
elif [[ "$cur" != "$(cat /root/.cka-coredns-Corefile)" ]]; then
  kubectl -n kube-system get configmap coredns -o json | jq --rawfile c /root/.cka-coredns-Corefile '.data.Corefile = $c' | kubectl replace -f - >/dev/null
  kubectl -n kube-system rollout restart deployment/coredns >/dev/null
  kubectl -n kube-system rollout status deployment/coredns --timeout=240s >/dev/null
fi
kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q1_NS}" create deployment web --image=nginx:1.27-alpine --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q1_NS}" expose deployment web --port=80 --dry-run=client -o yaml | kubectl apply -f - >/dev/null
kubectl -n "${Q1_NS}" delete pod dns-test --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q1_NS}" run dns-test --image=busybox:1.36 -- sleep infinity >/dev/null
kubectl -n "${Q1_NS}" rollout status deployment/web --timeout=180s >/dev/null
kubectl -n "${Q1_NS}" wait --for=condition=Ready pod/dns-test --timeout=120s >/dev/null
: "${Q1_NS}" "${Q1_HOST}" "${Q1_IP}"
